import{G as e,W as t,n,rt as r}from"./chunks/framework.DpaCCLuo.js";var i=JSON.parse(`{"title":"FAQ","description":"インストールボタンが押せない、VRChatでリップシンクしない、口の見た目が違うなど、Mururu Blink & LipSyncのよくある質問と表示されるメッセージへの対処。","frontmatter":{"description":"インストールボタンが押せない、VRChatでリップシンクしない、口の見た目が違うなど、Mururu Blink & LipSyncのよくある質問と表示されるメッセージへの対処。","head":[["link",{"rel":"canonical","href":"https://docs.unlibra.com/mururu-blink-lipsync/faq"}],["meta",{"property":"og:url","content":"https://docs.unlibra.com/mururu-blink-lipsync/faq"}],["meta",{"property":"og:title","content":"FAQ"}],["meta",{"property":"og:description","content":"インストールボタンが押せない、VRChatでリップシンクしない、口の見た目が違うなど、Mururu Blink & LipSyncのよくある質問と表示されるメッセージへの対処。"}]]},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1792943004000}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><h2 id="インストールボタンが押せない" tabindex="-1">インストールボタンが押せない <a class="header-anchor" href="#インストールボタンが押せない" aria-label="Permalink to “インストールボタンが押せない”">​</a></h2><p>「対象アバター」は選択されていますか？Hierarchyでシーンに置いたムルルを選択するか、「対象アバター」にドラッグしてください。Playモード中は操作できません。</p><h2 id="ムルルのアバターがピンクになっている" tabindex="-1">ムルルのアバターがピンクになっている <a class="header-anchor" href="#ムルルのアバターがピンクになっている" aria-label="Permalink to “ムルルのアバターがピンクになっている”">​</a></h2><p>プロジェクトにlilToonを追加してください。ムルルはlilToonを使っているため、別に追加する必要があります。</p><p>lilToonは<a href="https://lilxyzw.github.io/lilToon/ja_JP/" target="_blank" rel="noreferrer">こちら</a>です。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>インストールしたあとVCCのManage Packagesでプロジェクトに追加するのを忘れないようにしてください。</p></div><h2 id="unityでリップシンク用の口が表示されない" tabindex="-1">Unityでリップシンク用の口が表示されない <a class="header-anchor" href="#unityでリップシンク用の口が表示されない" aria-label="Permalink to “Unityでリップシンク用の口が表示されない”">​</a></h2><p>Unityの編集画面では、常に元の表情の口が表示されます。リップシンク用の口は、VRChatで話している間だけ表示されます。言葉の切れ目で口がちらつかないよう、声が途切れてもすぐには切り替えず、短い待ち時間を設けています。</p><p>Unity上でリップシンク用の口を確認したいときは、BlendShapeの値を次のように変えてください。</p><table tabindex="0"><thead><tr><th>オブジェクト</th><th>BlendShape</th><th>値</th></tr></thead><tbody><tr><td>Body</td><td><code>mouth_off</code></td><td>100</td></tr><tr><td>MururuBlinkLipSync &gt; LipSync_Mouth</td><td><code>SE_hide_self</code></td><td>0</td></tr><tr><td>MururuBlinkLipSync &gt; LipSync_Mouth</td><td><code>SE_mouth_A</code>・<code>SE_mouth_I</code>・<code>SE_mouth_U</code>・<code>SE_mouth_E</code>・<code>SE_mouth_O</code></td><td>合計が100以下になるように調整</td></tr></tbody></table><p>確認が終わったら、<code>mouth_off</code> を0、<code>SE_hide_self</code> を100、AIUEOのBlendShapeを0に戻してください。</p><h2 id="リップシンク用の口の見た目が顔と違う" tabindex="-1">リップシンク用の口の見た目が顔と違う <a class="header-anchor" href="#リップシンク用の口の見た目が顔と違う" aria-label="Permalink to “リップシンク用の口の見た目が顔と違う”">​</a></h2><p>リップシンク用の口は、アップロード時にBodyのマテリアルやライティングの設定に自動で合わせます。Bodyのマテリアルを差し替えても、インストールし直す必要はありません。ただし、メニューやアニメーションで切り替えるマテリアルには追従しません。</p><h2 id="vrchatでリップシンクしない" tabindex="-1">VRChatでリップシンクしない <a class="header-anchor" href="#vrchatでリップシンクしない" aria-label="Permalink to “VRChatでリップシンクしない”">​</a></h2><p>マイクがミュートになっていないか、リップシンクを止める表情（LipSync のチェックを外した表情）になっていないか確認してください。</p><h2 id="「滑らかな口の復帰を使えない条件があります」と表示される" tabindex="-1">「滑らかな口の復帰を使えない条件があります」と表示される <a class="header-anchor" href="#「滑らかな口の復帰を使えない条件があります」と表示される" aria-label="Permalink to “「滑らかな口の復帰を使えない条件があります」と表示される”">​</a></h2><p>ビルド時のNDMF警告に、滑らかな復帰を使えない表情・条件と理由を表示します。その範囲では全部または一部の組み合わせが瞬時切り替えになります。アップロードは継続できます。</p><p>口の形状を生成できない場合のほか、対応外の口シェイプが有効な場合や、FXから復帰先の口を確定できない場合に表示します。口に関係のない名前のシェイプでも、実際に口の頂点を動かしていれば判定の対象になります。設定でリップシンクを止めた表情については、警告を省きます。</p><h2 id="喋ると出てくる音符を消したい" tabindex="-1">喋ると出てくる音符を消したい <a class="header-anchor" href="#喋ると出てくる音符を消したい" aria-label="Permalink to “喋ると出てくる音符を消したい”">​</a></h2><p>設定画面の <strong>発話時の音符を非表示</strong> にチェックを入れ、<strong>設定の変更を適用</strong> を押してからアップロードしてください。元のFXを書き換えずに音符を非表示にできます。チェックを外すと、元のFXの設定を使います。</p><p>手動で調整する場合は、<code>Mururu_FX</code>コントローラーの<code>Facial LipSync</code>レイヤーのウェイトを<code>0</code>にすると無効化されます。このレイヤーに音符以外の効果を追加している場合は、その効果も止まります。</p><h2 id="「標準のmururuと異なる可能性があります」と表示される" tabindex="-1">「標準のMururuと異なる可能性があります」と表示される <a class="header-anchor" href="#「標準のmururuと異なる可能性があります」と表示される" aria-label="Permalink to “「標準のMururuと異なる可能性があります」と表示される”">​</a></h2><p>別体型のムルルや、頭部・口周辺を改変したBody、FBXのScale設定を変更したBodyで表示されます。続行すると、VRChatで話したときに口がずれて表示されることがあります。問題があれば <strong>アンインストール</strong> で元に戻せます。</p><h2 id="「mouth-aから対応するaiueo口頂点を特定できませんでした」と表示される" tabindex="-1">「mouth_Aから対応するAIUEO口頂点を特定できませんでした」と表示される <a class="header-anchor" href="#「mouth-aから対応するaiueo口頂点を特定できませんでした」と表示される" aria-label="Permalink to “「mouth_Aから対応するAIUEO口頂点を特定できませんでした」と表示される”">​</a></h2><p>Bodyの口周辺のメッシュや <code>mouth_A</code> の変更、FBXの座標軸・スケールの違いで表示されます。口を編集していなくても、Blenderからの書き出しで座標軸が変わる場合があります。</p><p>「口の前方向: +Y（標準: +Z）」と表示される場合は、次の項目を確認してください。それ以外は、まず改変前のBodyで導入できるか確認してください。</p><h2 id="body-axis" tabindex="-1">Bodyの座標軸が標準ムルルと異なる <a class="header-anchor" href="#body-axis" aria-label="Permalink to “Bodyの座標軸が標準ムルルと異なる”">​</a></h2><p>見た目が同じでも、FBX内部で口が動く方向が異なると、口を抽出できません。UnityのTransformの回転値だけを0にすると、見た目や骨の変形が変わるため、メッシュの座標も合わせて補正します。</p><p>以下は、エラーに <strong>口の前方向: +Y（標準: +Z）</strong> と表示されるモデルで確認した手順です。Blender 5.2.1 LTSの <strong>FBX（Legacy）</strong> で検証しています。他の軸や、FBX内にアニメーションを同梱したモデルは未検証です。</p><ol><li>FBXとBlenderファイルをバックアップし、コピーで作業します。</li><li>Blenderで対象のFBXを読み込みます。オブジェクトモードで、口のシェイプキーがあるBodyだけを選択します。アーマチュアは選択しません。</li><li>Bodyの回転がXYZとも0°であることを確認します。異なる場合は、この手順をそのまま実行しないでください。トランスフォーム座標系は <strong>グローバル</strong> にします。</li><li><code>R</code> → <code>X</code> → <code>90</code> → <code>Enter</code> で回転させます。</li><li><code>Ctrl+A</code> → <strong>回転</strong> を実行します。</li><li><code>R</code> → <code>X</code> → <code>-90</code> → <code>Enter</code> で見た目を元に戻します。最後の回転は適用しません。</li><li>Bodyとアーマチュアなど必要なオブジェクトを含め、別名のFBXへ書き出します。検証時の設定は次のとおりです。</li></ol><table tabindex="0"><thead><tr><th>設定</th><th>値</th></tr></thead><tbody><tr><td>Scale</td><td>1</td></tr><tr><td>Apply Scalings</td><td>FBX All</td></tr><tr><td>Forward / Up</td><td>-Z Forward / Y Up</td></tr><tr><td>Apply Unit / Use Space Transform</td><td>ON</td></tr><tr><td>Apply Transform / Apply Modifiers</td><td>OFF</td></tr><tr><td>Add Leaf Bones / Bake Animation</td><td>OFF</td></tr></tbody></table><p>Unityでコピーを読み込み、口の位置、AIUEO、既存の表情、頭・腕の動きを確認してから差し替えてください。確認したモデルでは、全7,043頂点・173シェイプと頭・腕の骨変形の差は最大約0.001mmで、口の抽出・生成も成功しました。</p><div class="tip custom-block"><p class="custom-block-title">対応範囲</p><p>この手順は座標軸による導入エラーへの対処です。補正後は、実際の口の構造とシェイプから表情ごとに滑らかな復帰が可能か判定します。口以外のBody改変だけで全体が無効にはなりません。対応できない表情だけ、無音から80ms後の瞬間切替になります。任意の口構造や表情Controllerへの対応を保証するものではありません。</p></div><h2 id="「bodyの親がavatar-rootか確認してください」と表示される" tabindex="-1">「Bodyの親がAvatar Rootか確認してください」と表示される <a class="header-anchor" href="#「bodyの親がavatar-rootか確認してください」と表示される" aria-label="Permalink to “「Bodyの親がAvatar Rootか確認してください」と表示される”">​</a></h2><p>BodyをアバターのRoot直下に置いてください。</p><h2 id="「facial-exパラメータがexpression-parametersとma-parametersに見つかりません」と表示される" tabindex="-1">「Facial EXパラメータがExpression ParametersとMA Parametersに見つかりません」と表示される <a class="header-anchor" href="#「facial-exパラメータがexpression-parametersとma-parametersに見つかりません」と表示される" aria-label="Permalink to “「Facial EXパラメータがExpression ParametersとMA Parametersに見つかりません」と表示される”">​</a></h2><p>MA Menu Itemなどで作られるパラメータの場合は、そのまま続行できます。名前が間違っている場合は、<a href="./settings#詳細設定">詳細設定</a> でパラメータ名を確認してください。</p>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};